local OilPresser = {}
local PRODUCTS = {
    olive_oil = { name = "Oljčno olje", oliveCost = 3, time = 2, cost = 22, purity = 60, happiness = 1, description = "Oljčno olje za kuhanje in prižiganje." },
    walnut_oil = { name = "Orehovo olje", walnutCost = 3, time = 3, cost = 50, purity = 70, happiness = 2, prestige = 1, description = "Orehovo olje z bogatim okusom." },
    linseed_oil = { name = "Laneno olje", flaxCost = 3, time = 3, cost = 55, purity = 75, happiness = 2, prestige = 2, description = "Laneno olje za barve in zaščito lesa." },
    poppy_oil = { name = "Makovo olje", poppyCost = 4, time = 5, cost = 130, purity = 85, happiness = 3, prestige = 4, description = "Makovo olje za fine jedi." },
    silver_infused_oil = { name = "Srebrno ojačano olje", oliveCost = 5, silverCost = 1, time = 8, cost = 320, purity = 95, happiness = 5, prestige = 11, description = "Olje s srebrno korekcijo za kraljeve jedi." },
    royal_grand_oil = { name = "Kraljevski veliki olje", oliveCost = 8, walnutCost = 4, goldCost = 1, silverCost = 1, jewelCost = 1, time = 14, cost = 1200, purity = 100, happiness = 12, prestige = 32, description = "Veliko kraljevsko olje z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Oljarska delavnica", cost = { gold = 280, wood = 150, stone = 200 }, upkeep = 7, qualityBonus = 5 },
    press_house = { name = "Tisčnica", cost = { gold = 950, wood = 280, stone = 400, iron = 8 }, upkeep = 23, qualityBonus = 18 },
    filtration_room = { name = "Filtrirnica", cost = { gold = 2300, wood = 350, stone = 700, silver = 30, clay = 8 }, upkeep = 58, qualityBonus = 30 },
    royal_oil_atelier = { name = "Kraljevski atelje olja", cost = { gold = 9000, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 180, qualityBonus = 55, prestigeBonus = 40 },
}
OilPresser.oliveStock = 20; OilPresser.walnutStock = 16; OilPresser.flaxStock = 14; OilPresser.poppyStock = 10; OilPresser.silverStock = 8; OilPresser.goldStock = 6; OilPresser.jewelStock = 6
OilPresser.productStock = {}; OilPresser.buildings = {}; OilPresser.maker = nil; OilPresser.activeMaking = {}; OilPresser.totalProducts = 0; OilPresser.dayTimer = 0
function OilPresser.init() OilPresser.oliveStock=20; OilPresser.walnutStock=16; OilPresser.flaxStock=14; OilPresser.poppyStock=10; OilPresser.silverStock=8; OilPresser.goldStock=6; OilPresser.jewelStock=6; OilPresser.productStock={}; OilPresser.buildings={}; OilPresser.maker=nil; OilPresser.activeMaking={}; OilPresser.totalProducts=0; OilPresser.dayTimer=0; print("[OilPresser] Royal Oil Presser System initialized (6 products, 4 buildings)") end
function OilPresser.hireMaker(n,s) s=s or math.random(50,90); local c=510+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; OilPresser.maker={name=n or ("Oljar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Oljar najet: %s (spretnost: %d)",OilPresser.maker.name,s),"success") end; return true end
function OilPresser.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function OilPresser.build(id) local ok,e=OilPresser.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(OilPresser.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function OilPresser.getQualityBonus() local b=0; for _,bd in ipairs(OilPresser.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function OilPresser.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.oliveCost and OilPresser.oliveStock<(d.oliveCost or 0) then return false,"Premalo oljk" end; if d.walnutCost and OilPresser.walnutStock<(d.walnutCost or 0) then return false,"Premalo orehov" end; if d.flaxCost and OilPresser.flaxStock<(d.flaxCost or 0) then return false,"Premalo lana" end; if d.poppyCost and OilPresser.poppyStock<(d.poppyCost or 0) then return false,"Premalo maka" end; if d.silverCost and OilPresser.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and OilPresser.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and OilPresser.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #OilPresser.buildings==0 then return false,"Potrebna delavnica" end; if not OilPresser.maker then return false,"Potreben oljar" end; return true end
function OilPresser.make(pt,qty) qty=qty or 5; local ok,e=OilPresser.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.oliveCost then OilPresser.oliveStock=OilPresser.oliveStock-d.oliveCost*qty end; if d.walnutCost then OilPresser.walnutStock=OilPresser.walnutStock-d.walnutCost*qty end; if d.flaxCost then OilPresser.flaxStock=OilPresser.flaxStock-d.flaxCost*qty end; if d.poppyCost then OilPresser.poppyStock=OilPresser.poppyStock-d.poppyCost*qty end; if d.silverCost then OilPresser.silverStock=OilPresser.silverStock-d.silverCost*qty end; if d.goldCost then OilPresser.goldStock=OilPresser.goldStock-d.goldCost*qty end; if d.jewelCost then OilPresser.jewelStock=OilPresser.jewelStock-d.jewelCost*qty end; local t=d.time; if OilPresser.maker then t=math.max(1,t-math.floor(OilPresser.maker.skill/12)) end; table.insert(OilPresser.activeMaking,{id="oil_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,purity=d.purity or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function OilPresser.completeMaking(m) local q=1.0+(OilPresser.getQualityBonus()/100); if OilPresser.maker then q=q+(OilPresser.maker.skill/180) end; q=math.min(2.0,q); OilPresser.productStock[m.productType]=(OilPresser.productStock[m.productType] or 0)+m.quantity; OilPresser.totalProducts=OilPresser.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if OilPresser.maker then OilPresser.maker.itemsMade=OilPresser.maker.itemsMade+m.quantity; if math.random()<0.20 then OilPresser.maker.skill=math.min(100,OilPresser.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Olje izdelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"oil.completed",{productName=m.productName,purity=m.purity,happiness=m.happiness}) end end
function OilPresser.update(dt) if not _G.state then return end; OilPresser.dayTimer=OilPresser.dayTimer+dt; if OilPresser.dayTimer>=30 then OilPresser.dayTimer=0; for i=#OilPresser.activeMaking,1,-1 do local m=OilPresser.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then OilPresser.completeMaking(m); table.remove(OilPresser.activeMaking,i) end end; local tu=0; for _,bd in ipairs(OilPresser.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if OilPresser.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function OilPresser.getStats() return {oliveStock=OilPresser.oliveStock,walnutStock=OilPresser.walnutStock,flaxStock=OilPresser.flaxStock,poppyStock=OilPresser.poppyStock,silverStock=OilPresser.silverStock,goldStock=OilPresser.goldStock,jewelStock=OilPresser.jewelStock,productStock=OilPresser.productStock,numBuildings=#OilPresser.buildings,hasMaker=OilPresser.maker~=nil,makerName=OilPresser.maker and OilPresser.maker.name or "—",makerSkill=OilPresser.maker and OilPresser.maker.skill or 0,activeMaking=#OilPresser.activeMaking,totalProducts=OilPresser.totalProducts} end
return OilPresser
